/* XLSX first-sheet import/export. JSZip is bundled locally; no CDN required. */
(function(){'use strict';
const esc=s=>String(s??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));
const col=n=>{let r='';do{r=String.fromCharCode(n%26+65)+r;n=Math.floor(n/26)-1;}while(n>=0);return r;};
function csv(text,delimiter=','){let rows=[],row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&(quote||cell==='')){if(quote&&text[i+1]==='"'){cell+='"';i++;}else quote=!quote;}else if(!quote&&c===delimiter){row.push(cell);cell='';}else if(!quote&&(c==='\n'||c==='\r')){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v!==''))rows.push(row);row=[];cell='';}else cell+=c;}if(quote)throw Error('따옴표가 닫히지 않은 CSV/TSV 파일입니다.');row.push(cell);if(row.some(v=>v!==''))rows.push(row);return rows;}
const parse=x=>{const doc=new DOMParser().parseFromString(x,'application/xml');if(doc.querySelector('parsererror'))throw Error('엑셀 내부 XML을 읽을 수 없습니다.');return doc;};
async function read(file){
 let matrix;
 if(/\.(csv|tsv)$/i.test(file.name)){let bytes=await file.arrayBuffer();let text=new TextDecoder('utf-8').decode(bytes);if(text.includes('\uFFFD'))text=new TextDecoder('euc-kr').decode(bytes);matrix=csv(text.replace(/^\uFEFF/,''),/\.tsv$/i.test(file.name)?'\t':',');}
 else if(/\.xlsx$/i.test(file.name)){
 const zip=await JSZip.loadAsync(await file.arrayBuffer());const xml=async path=>{const f=zip.file(path);if(!f)throw Error('올바른 XLSX 파일이 아닙니다: '+path);return parse(await f.async('string'));};
 const wb=await xml('xl/workbook.xml');const sheet=wb.getElementsByTagName('sheet')[0];if(!sheet)throw Error('시트가 없습니다.');const rid=sheet.getAttribute('r:id');const rels=await xml('xl/_rels/workbook.xml.rels');const target=[...rels.getElementsByTagName('Relationship')].find(r=>r.getAttribute('Id')===rid)?.getAttribute('Target');if(!target)throw Error('시트 경로를 찾을 수 없습니다.');let path=target.startsWith('/')?target.slice(1):'xl/'+target;path=path.split('/').reduce((a,p)=>p==='..'?(a.pop(),a):p==='.'?a:(a.push(p),a),[]).join('/');
 let strings=[];if(zip.file('xl/sharedStrings.xml'))strings=[...(await xml('xl/sharedStrings.xml')).getElementsByTagName('si')].map(si=>[...si.getElementsByTagName('t')].map(t=>t.textContent).join(''));
 let dateStyles=new Set();if(zip.file('xl/styles.xml')){const styles=await xml('xl/styles.xml');const dateIds=new Set([14,15,16,17,18,19,20,21,22,45,46,47]);[...styles.getElementsByTagName('numFmt')].forEach(n=>{if(/[yd]/i.test((n.getAttribute('formatCode')||'').replace(/"[^"]*"/g,'')))dateIds.add(Number(n.getAttribute('numFmtId')));});const xfs=styles.getElementsByTagName('cellXfs')[0];[...(xfs?.children||[])].forEach((x,i)=>{if(dateIds.has(Number(x.getAttribute('numFmtId'))))dateStyles.add(i);});}
 const ws=await xml(path);const date1904=['1','true'].includes(wb.getElementsByTagName('workbookPr')[0]?.getAttribute('date1904'));matrix=[...ws.getElementsByTagName('row')].map(r=>{const row=[];[...r.getElementsByTagName('c')].forEach(c=>{let i=0;for(const ch of (c.getAttribute('r')||'A').replace(/[0-9]/g,''))i=i*26+ch.charCodeAt(0)-64;const type=c.getAttribute('t');let value=c.getElementsByTagName('v')[0]?.textContent||'';if(type==='s')value=strings[Number(value)]||'';else if(type==='inlineStr')value=[...c.getElementsByTagName('t')].map(t=>t.textContent).join('');else if(type==='b')value=value==='1'?'TRUE':'FALSE';else if(value!==''&&dateStyles.has(Number(c.getAttribute('s')))){const epoch=date1904?Date.UTC(1904,0,1):Date.UTC(1899,11,30);value=new Date(epoch+Number(value)*86400000).toISOString().slice(0,10);}row[i-1]=value;});return row;}).filter(r=>r.some(v=>v!==''&&v!=null));
 }else throw Error('XLSX 또는 CSV 파일을 선택해 주세요. XLS 파일은 XLSX로 저장한 뒤 불러오세요.');
 if(matrix.length<1)throw Error('파일에 데이터가 없습니다.');const header=matrix.shift();const columns=Array.from({length:matrix.reduce((n,r)=>Math.max(n,r.length),header.length)},(_,i)=>String(header[i]??'').trim()||'열'+(i+1));if(new Set(columns).size!==columns.length)throw Error('중복된 열 이름이 있습니다.');const rows=matrix.map(row=>Object.fromEntries(columns.map((c,i)=>[c,String(row[i]??'')])));return {columns,rows};
}
async function blob(columns,rows){const zip=new JSZip();const ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main';zip.file('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>');zip.file('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');zip.file('xl/workbook.xml','<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="'+ns+'" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="데이터" sheetId="1" r:id="rId1"/></sheets></workbook>');zip.file('xl/_rels/workbook.xml.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>');const matrix=[columns,...rows.map(r=>columns.map(c=>r[c]??''))];zip.file('xl/worksheets/sheet1.xml','<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="'+ns+'"><sheetData>'+matrix.map((r,i)=>'<row r="'+(i+1)+'">'+r.map((v,j)=>'<c r="'+col(j)+(i+1)+'" t="inlineStr"><is><t xml:space="preserve">'+esc(v)+'</t></is></c>').join('')+'</row>').join('')+'</sheetData></worksheet>');return zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});}
function download(data,name){const url=URL.createObjectURL(data instanceof Blob?data:new Blob([data],{type:'application/octet-stream'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
window.ExcelIO={read,blob,download};})();
